const r = await api.get("/customers", { tier: "gold" });
if (Array.isArray(r)) return { 형태: "배열", 골드고객수: r.length };
return { 형태: "객체", 키: Object.keys(r), 전체개수: r.total ?? r.count ?? null, 항목수: Array.isArray(r.items) ? r.items.length : (Array.isArray(r.data) ? r.data.length : null) };

